  "ui.mediaStarter.image1.title": "Retrato editorial",
  "ui.mediaStarter.image1.tag": "Retrato",
  "ui.mediaStarter.image1.prompt": "Um retrato editorial em close de uma pessoa no fim dos 20 anos que atua como diretora criativa, luz natural suave por janelas altas de estúdio, paleta neutra quente (creme, taupe, preto suave), fotografado em 85 mm f/1.8 com pouca profundidade de campo, olhar firme para a câmera, granulação sutil de filme, aparência sem maquiagem.",
  "ui.mediaStarter.image2.title": "Imagem principal de produto",
  "ui.mediaStarter.image2.tag": "E-commerce",
  "ui.mediaStarter.image2.prompt": "Uma foto principal premium de uma única caneca de café de cerâmica fosca sobre um fundo de papel creme quente. Luz de recorte dura no alto à esquerda, sombra suave alongada para baixo à direita, vapor discreto saindo da xícara. Recorte quadrado, composição centralizada, espaço acima para o título, sem objetos extras nem mãos.",
  "ui.mediaStarter.image3.title": "Ilustração plana",
  "ui.mediaStarter.image3.tag": "Ilustração",
  "ui.mediaStarter.image3.prompt": "Uma ilustração vetorial plana de um canto aconchegante de leitura junto a uma janela com chuva: formas geométricas, paleta contida de cinco cores (creme, terracota, verde-petróleo escuro, siena queimada, preto suave), traços finos de 1.5px, sem gradientes nem texturas, sombras suaves apenas na poltrona em primeiro plano.",
  "ui.mediaStarter.video1.title": "Revelação de produto",
  "ui.mediaStarter.video1.tag": "Cinematográfico",
  "ui.mediaStarter.video1.prompt": "Uma revelação de produto de 5 segundos: um frasco minimalista de skincare premium sobre pedra creme limpa, luz lateral suave à esquerda da câmera, aproximação lenta, mudança sutil de foco da tampa para o rótulo, movimento contido, sem textos sobrepostos nem pessoas.",
  "ui.mediaStarter.video2.title": "Lanterna em close",
  "ui.mediaStarter.video2.tag": "Atmosfera",
  "ui.mediaStarter.video2.prompt": "Um close cinematográfico de 6 segundos de uma jovem segurando uma lanterna de papel acesa em uma floresta de pinheiros com neblina na hora dourada. Pouca profundidade de campo nos olhos, aproximação suave, partículas flutuando no feixe quente, sem diálogo, apenas sons da floresta.",
  "ui.mediaStarter.video3.title": "Drift em rua neon",
  "ui.mediaStarter.video3.tag": "Ação",
  "ui.mediaStarter.video3.prompt": "Uma tomada de acompanhamento de corrida de rua de 5 segundos, à noite, em um beco cyberpunk de Hong Kong iluminado por neon. Câmera baixa seguindo um esportivo preto fosco em drift numa curva fechada, desfoque nas rodas, reflexos de lente dos letreiros neon, asfalto molhado refletindo as luzes, sem texto na tela.",
  "ui.mediaStarter.hyperframes1.title": "Revelação com lupa",
  "ui.mediaStarter.hyperframes1.tag": "HTML-in-canvas",
  "ui.mediaStarter.hyperframes1.prompt": "Crie uma composição de 5 segundos com uma linha de texto de destaque em negrito em uma tela limpa. Anime uma lupa redonda da esquerda para a direita sobre a linha, com refração sutil deformando as letras. Use HyperFrames html-in-canvas: capture o DOM do texto e aplique um shader de lente por cima em uma etapa no estilo vfx-liquid-glass. CSS puro no texto; o vidro é uma camada WebGL.",
  "ui.mediaStarter.hyperframes2.title": "Cena de terminal CRT",
  "ui.mediaStarter.hyperframes2.tag": "VFX retrô",
  "ui.mediaStarter.hyperframes2.prompt": "Crie uma composição de tela CRT: fundo escuro, texto monoespaçado de terminal digitando `npx hyperframes init my-video`, depois `claude` com o prompt “Adicione um efeito CRT usando HTML-in-canvas”. Aplique curvatura convexa sutil, linhas de varredura, leve aberração cromática e brilho suave de fósforo sobre o DOM ao vivo via html-in-canvas. O texto continua em CSS real para ficar nítido antes do shader.",
  "ui.mediaStarter.hyperframes3.title": "Desintegração glitch",
  "ui.mediaStarter.hyperframes3.tag": "Glitch",
  "ui.mediaStarter.hyperframes3.prompt": "Crie uma composição de 6 segundos com um título principal e um subtítulo de uma linha em fundo escuro, seguida de um glitch digital forte: separação de canais RGB, faixas de deslocamento horizontal, breve travamento de quadros e retorno limpo ao final. Capture o DOM ao vivo via html-in-canvas e aplique o glitch por cima, mantendo a tipografia em CSS real sob o shader.",
  "ui.mediaStarter.audio1.title": "Locução de marca",
  "ui.mediaStarter.audio1.tag": "Fala",
  "ui.mediaStarter.audio1.prompt": "Uma locução narrativa calorosa de 30 segundos para um vídeo de lançamento: confiante, mas conversacional, ritmo médio e uma pausa após a marca. Roteiro: 'Three years in the making. One simple promise. Meet [product name] — the way work was supposed to feel.' Em inglês, com sotaque norte-americano neutro.",
  "ui.mediaStarter.audio2.title": "Narração de boas-vindas",
  "ui.mediaStarter.audio2.tag": "Fala",
  "ui.mediaStarter.audio2.prompt": "Uma narração amigável de boas-vindas de 20 segundos para a primeira abertura de um app móvel. Tom tranquilizador e sorridente, lento o bastante para transmitir atenção sem parecer leitura. Roteiro: “Boas-vindas ao Loop. Vamos preparar seu espaço: três perguntas rápidas e pronto. Você pode mudar tudo depois.”",
  "ui.mediaStarter.audio3.title": "Leitura de trecho narrativo",
  "ui.mediaStarter.audio3.tag": "Fala",
  "ui.mediaStarter.audio3.prompt": "Uma leitura cinematográfica de 45 segundos de um trecho de abertura. Voz baixa e medida, com respiração entre frases e intimidade de microfone próximo. Roteiro: “A cidade dorme em pedaços. Um letreiro neon pisca sobre o balcão de ramen. Do outro lado da avenida, uma janela brilha: a única ainda acesa deste lado da meia-noite.”",
